#include "sound.h"

#include "alarm-sound-data.h" // generated by CMake: ttime_alarm_sound[], ttime_alarm_sound_size

#include <slint.h>

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>

#ifdef _WIN32
#    define WIN32_LEAN_AND_MEAN
#    define NOMINMAX
#    include <windows.h>
#    include <mmsystem.h>
#else
#    include <filesystem>
#    include <fstream>
#    include <signal.h>
#    include <spawn.h>
#    include <sys/wait.h>
#    include <unistd.h>
extern char **environ;
#endif

using namespace std::chrono;

namespace {

std::uint32_t readLe32(const std::uint8_t *p)
{
    return p[0] | (p[1] << 8) | (p[2] << 16) | (static_cast<std::uint32_t>(p[3]) << 24);
}

std::span<const std::uint8_t> alarmSoundData()
{
    return {ttime_alarm_sound, ttime_alarm_sound_size};
}

} // namespace

std::optional<milliseconds> wavDuration(std::span<const std::uint8_t> data)
{
    if (data.size() < 12 || std::memcmp(data.data(), "RIFF", 4) != 0 || std::memcmp(data.data() + 8, "WAVE", 4) != 0) {
        return std::nullopt;
    }
    std::uint32_t byteRate = 0;
    std::size_t pos = 12;
    while (pos + 8 <= data.size()) {
        const std::uint8_t *header = data.data() + pos;
        const std::uint32_t chunkSize = readLe32(header + 4);
        pos += 8;
        if (std::memcmp(header, "fmt ", 4) == 0) {
            if (chunkSize < 16 || pos + 16 > data.size()) {
                return std::nullopt;
            }
            byteRate = readLe32(data.data() + pos + 8);
        } else if (std::memcmp(header, "data", 4) == 0) {
            if (byteRate == 0) {
                return std::nullopt; // "fmt " must come before "data"
            }
            return milliseconds{static_cast<long long>(chunkSize) * 1000 / byteRate};
        }
        pos += chunkSize + (chunkSize & 1U); // + pad byte for odd sizes
    }
    return std::nullopt;
}

int loopsForDuration(milliseconds clip, milliseconds target)
{
    if (clip <= 0ms) {
        return 1;
    }
    const double loops = std::round(static_cast<double>(target.count()) / static_cast<double>(clip.count()));
    return std::max(1, static_cast<int>(loops));
}

struct AlarmSound::Private
{
    slint::Timer stopTimer;
#ifndef _WIN32
    pid_t player = -1;
#endif
};

AlarmSound::AlarmSound(milliseconds target)
    : d(new Private)
{
    const auto data = alarmSoundData();
    const auto clip = wavDuration(data);
    if (!clip) {
        std::fprintf(stderr, "tTime: cannot read the length of the alarm sound; playing it once\n");
    }
    const int loops = clip ? loopsForDuration(*clip, target) : 1;

#ifdef _WIN32
    // Played from memory; winmm.dll is delay-loaded, so it is only mapped when an alarm rings.
    const auto *wav = reinterpret_cast<LPCWSTR>(data.data());
    if (loops > 1) {
        PlaySoundW(wav, nullptr, SND_MEMORY | SND_ASYNC | SND_LOOP | SND_NODEFAULT);
        d->stopTimer.start(slint::TimerMode::SingleShot, *clip * loops, [this] { stop(); });
    } else {
        PlaySoundW(wav, nullptr, SND_MEMORY | SND_ASYNC | SND_NODEFAULT);
    }
#else
    // macOS: afplay; Linux: paplay (PulseAudio/PipeWire) or aplay (ALSA), looped by a shell.
    namespace fs = std::filesystem;
    std::error_code error;
    const fs::path file = fs::temp_directory_path(error) / "tTime-alarm.wav";
    std::ofstream(file, std::ios::binary).write(reinterpret_cast<const char *>(data.data()), static_cast<std::streamsize>(data.size()));
#    ifdef __APPLE__
    const std::string player = "afplay";
#    else
    const std::string player = "{ command -v paplay >/dev/null && p=paplay || p=aplay; }; $p";
#    endif
    const std::string script = "for i in $(seq " + std::to_string(loops) + "); do " + player + " '" + file.string()
        + "' >/dev/null 2>&1 || break; done";
    const char *argv[] = {"/bin/sh", "-c", script.c_str(), nullptr};
    posix_spawnattr_t attributes;
    posix_spawnattr_init(&attributes);
    posix_spawnattr_setflags(&attributes, POSIX_SPAWN_SETPGROUP); // own group: stop() ends the player too
    posix_spawnattr_setpgroup(&attributes, 0);
    if (posix_spawn(&d->player, "/bin/sh", nullptr, &attributes, const_cast<char **>(argv), environ) != 0) {
        d->player = -1;
        std::fprintf(stderr, "tTime: cannot play the alarm sound\n");
    }
    posix_spawnattr_destroy(&attributes);
#endif
}

AlarmSound::~AlarmSound()
{
    stop();
    delete d;
}

void AlarmSound::stop()
{
    d->stopTimer.stop();
#ifdef _WIN32
    PlaySoundW(nullptr, nullptr, 0);
#else
    if (d->player > 0) {
        kill(-d->player, SIGTERM);
        waitpid(d->player, nullptr, 0);
        d->player = -1;
    }
#endif
}
